// Set this to an address reachable from your n8n server.
// For Docker, localhost is the n8n container, not the PeopleOS host.
const baseUrl = 'http://127.0.0.1:3001';
return [{ json: { baseUrl: baseUrl.replace(/\/$/, ''), scenario: 'migration' } }];

const response = $input.first().json;
const config = $('Configure demo').first().json;
const raw = response.headers?.['set-cookie'] ?? response.headers?.['Set-Cookie'];
const cookies = Array.isArray(raw) ? raw : raw ? [raw] : [];
const cookie = cookies.map(value => String(value).split(';')[0]).join('; ');
if (!cookie) throw new Error('No session cookie received. Enable Include Response Headers and Status on Initialize workspace.');
if (!response.body?.employees) throw new Error('Unexpected workspace response. Check the PeopleOS base URL.');
return [{ json: { ...config, cookie, employeeCount: response.body.employees.length } }];

const run = $input.first().json;
const session = $('Preserve session').first().json;
if (run.status !== 'awaiting_approval') throw new Error('Expected a proposal awaiting human approval.');
return [{ json: {
  runId: run.id,
  status: run.status,
  summary: run.summary,
  steps: run.steps,
  proposal: run.proposal,
  syntheticRecords: session.employeeCount,
  recordsChangedByThisWorkflow: 0,
  nextStep: 'Review the proposal. This workflow deliberately stops before approval. The session is separate from your browser workspace.',
  manualApprovalRequest: {
    method: 'POST',
    url: `${session.baseUrl}/api/runs/${run.id}/approve`,
    headers: { 'Content-Type': 'application/json', Cookie: session.cookie },
    body: { decision: 'approve' }
  }
} }];
